module island_courier (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [1:0] n,\n    input wire [15:0] adj,\n    input wire [63:0] L,\n    output reg [15:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE      = 3'd0;\n    localparam [2:0] CHECK_ORIG= 3'd1;\n    localparam [2:0] ITER_START= 3'd2;\n    localparam [2:0] ITER_BODY = 3'd3;\n    localparam [2:0] EVALUATE  = 3'd4;\n    localparam [2:0] UPDATE    = 3'd5;\n    localparam [2:0] DONE_ST   = 3'd6;\n\n    reg [2:0] state, next_state;\n    reg [1:0] i_idx, j_idx;\n    reg [15:0] orig_adj_reg;\n    reg [15:0] new_adj;\n    reg [15:0] min_result;\n    reg [15:0] candidate;\n    reg strong_flag;\n    reg [7:0] cycle_count;\n    localparam [7:0] MAX_CYCLES = 8'd100;\n\n    function automatic is_strongly_connected;\n        input [15:0] adj_mat;\n        input [1:0] num_nodes;\n        integer i, j, k;\n        reg [15:0] reach;\n        begin\n            reach = adj_mat;\n            for (k = 0; k < 4; k = k + 1) begin\n                if (k < num_nodes + 1) begin\n                    for (i = 0; i < 4; i = i + 1) begin\n                        if (i < num_nodes + 1) begin\n                            for (j = 0; j < 4; j = j + 1) begin\n                                if (j < num_nodes + 1) begin\n                                    reach[i*4 + j] = reach[i*4 + j] | (reach[i*4 + k] & reach[k*4 + j]);\n                                end\n                            end\n                        end\n                    end\n                end\n            end\n            is_strongly_connected = 1'b1;\n            for (i = 0; i < num_nodes + 1; i = i + 1) begin\n                for (j = 0; j < num_nodes + 1; j = j + 1) begin\n                    if (i != j && reach[i*4 + j] != 1'b1) begin\n                        is_strongly_connected = 1'b0;\n                    end\n                end\n            end\n        end\n    endfunction\n\n    always @(*) begin\n        new_adj = orig_adj_reg;\n        if (state == ITER_BODY || state == EVALUATE) begin\n            if (i_idx < (n + 1) && j_idx < (n + 1)) begin\n                new_adj[i_idx*4 + j_idx] = 1'b1;\n                new_adj[j_idx*4 + i_idx] = 1'b1;\n            end\n        end\n        strong_flag = is_strongly_connected(new_adj, n);\n    end\n\n    function automatic [15:0] get_L;\n        input [63:0] L_mat;\n        input [1:0] i, j;\n        begin\n            get_L = L_mat[16*(i*4 + j) +: 16];\n        end\n    endfunction\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 16'h0;\n            done <= 1'b0;\n            min_result <= 16'hFFFF;\n            i_idx <= 2'b00;\n            j_idx <= 2'b00;\n            orig_adj_reg <= 16'h0;\n            candidate <= 16'h0;\n            cycle_count <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_count <= 8'd0;\n                    if (start) begin\n                        orig_adj_reg <= adj;\n                        state <= CHECK_ORIG;\n                        min_result <= 16'hFFFF;\n                    end\n                end\n\n                CHECK_ORIG: begin\n                    if (strong_flag) begin\n                        result <= 16'h0;\n                        done <= 1'b1;\n                        state <= DONE_ST;\n                    end else begin\n                        state <= ITER_START;\n                    end\n                end\n\n                ITER_START: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    i_idx <= 2'b00;\n                    j_idx <= 2'b00;\n                    state <= ITER_BODY;\n                end\n\n                ITER_BODY: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    if (i_idx > n || j_idx > n || orig_adj_reg[i_idx*4 + j_idx] == 1'b1 || cycle_count >= MAX_CYCLES) begin\n                        if (cycle_count < MAX_CYCLES) begin\n                            if (j_idx < n) begin\n                                j_idx <= j_idx + 1;\n                            end else begin\n                                j_idx <= 0;\n                                if (i_idx < n) begin\n                                    i_idx <= i_idx + 1;\n                                end else begin\n                                    state <= DONE_ST;\n                                end\n                            end\n                        end else begin\n                            state <= DONE_ST;\n                        end\n                    end else begin\n                        state <= EVALUATE;\n                    end\n                end\n\n                EVALUATE: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    if (strong_flag) begin\n                        candidate <= get_L(L, i_idx, j_idx) + get_L(L, j_idx, i_idx);\n                        state <= UPDATE;\n                    end else begin\n                        state <= ITER_BODY;\n                    end\n                end\n\n                UPDATE: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    if (candidate < min_result) begin\n                        min_result <= candidate;\n                    end\n                    state <= ITER_BODY;\n                end\n\n                DONE_ST: begin\n                    if (min_result != 16'hFFFF) begin\n                        result <= min_result;\n                    end else begin\n                        result <= 16'hFFFF;\n                    end\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule